package main

import (
	"encoding/json"
	"fmt"
	"io"
	"strconv"
	"strings"
)

type Kind int

const (
	NullKind Kind = iota
	BoolKind
	NumberKind
	StringKind
	ArrayKind
	ObjectKind
)

type ScalarStyle int

const (
	StylePlain ScalarStyle = iota
	StyleDoubleQuoted
)

type Value struct {
	Kind   Kind
	Bool   bool
	Number string
	String string
	Style  ScalarStyle
	Array  []*Value
	Object *Object
}

type Pair struct {
	Key   string
	Value *Value
}

type Object struct {
	Pairs []Pair
	index map[string]int
}

func newObject() *Object {
	return &Object{index: map[string]int{}}
}

func NullValue() *Value {
	return &Value{Kind: NullKind}
}

func BoolValue(v bool) *Value {
	return &Value{Kind: BoolKind, Bool: v}
}

func NumberValue(v string) *Value {
	return &Value{Kind: NumberKind, Number: v}
}

func StringValue(v string) *Value {
	return &Value{Kind: StringKind, String: v, Style: StylePlain}
}

func QuotedStringValue(v string) *Value {
	return &Value{Kind: StringKind, String: v, Style: StyleDoubleQuoted}
}

func ArrayValue(items []*Value) *Value {
	return &Value{Kind: ArrayKind, Array: items}
}

func ObjectValue(obj *Object) *Value {
	return &Value{Kind: ObjectKind, Object: obj}
}

func (o *Object) clone() *Object {
	out := newObject()
	for _, pair := range o.Pairs {
		out.Set(pair.Key, pair.Value.Clone())
	}
	return out
}

func (o *Object) Get(key string) (*Value, bool) {
	idx, ok := o.index[key]
	if !ok {
		return nil, false
	}
	return o.Pairs[idx].Value, true
}

func (o *Object) Set(key string, value *Value) {
	if value == nil {
		value = NullValue()
	}
	if idx, ok := o.index[key]; ok {
		o.Pairs[idx].Value = value
		return
	}
	o.index[key] = len(o.Pairs)
	o.Pairs = append(o.Pairs, Pair{Key: key, Value: value})
}

func (o *Object) Keys() []string {
	keys := make([]string, 0, len(o.Pairs))
	for _, pair := range o.Pairs {
		keys = append(keys, pair.Key)
	}
	return keys
}

func (v *Value) Clone() *Value {
	if v == nil {
		return NullValue()
	}
	switch v.Kind {
	case NullKind:
		return NullValue()
	case BoolKind:
		return BoolValue(v.Bool)
	case NumberKind:
		return NumberValue(v.Number)
	case StringKind:
		return &Value{Kind: StringKind, String: v.String, Style: v.Style}
	case ArrayKind:
		items := make([]*Value, 0, len(v.Array))
		for _, item := range v.Array {
			items = append(items, item.Clone())
		}
		return ArrayValue(items)
	case ObjectKind:
		return ObjectValue(v.Object.clone())
	default:
		return NullValue()
	}
}

func (v *Value) Truthy() bool {
	if v == nil {
		return false
	}
	switch v.Kind {
	case NullKind:
		return false
	case BoolKind:
		return v.Bool
	default:
		return true
	}
}

func (v *Value) Equal(other *Value) bool {
	if v == nil {
		v = NullValue()
	}
	if other == nil {
		other = NullValue()
	}
	if v.Kind != other.Kind {
		return false
	}
	switch v.Kind {
	case NullKind:
		return true
	case BoolKind:
		return v.Bool == other.Bool
	case NumberKind:
		return v.Number == other.Number
	case StringKind:
		return v.String == other.String
	case ArrayKind:
		if len(v.Array) != len(other.Array) {
			return false
		}
		for i := range v.Array {
			if !v.Array[i].Equal(other.Array[i]) {
				return false
			}
		}
		return true
	case ObjectKind:
		if len(v.Object.Pairs) != len(other.Object.Pairs) {
			return false
		}
		for i, pair := range v.Object.Pairs {
			otherPair := other.Object.Pairs[i]
			if pair.Key != otherPair.Key || !pair.Value.Equal(otherPair.Value) {
				return false
			}
		}
		return true
	default:
		return false
	}
}

func MergeValues(left, right *Value) *Value {
	if left == nil {
		return right.Clone()
	}
	if right == nil {
		return left.Clone()
	}
	if left.Kind == ObjectKind && right.Kind == ObjectKind {
		out := left.Clone()
		for _, pair := range right.Object.Pairs {
			existing, ok := out.Object.Get(pair.Key)
			if ok {
				out.Object.Set(pair.Key, MergeValues(existing, pair.Value))
			} else {
				out.Object.Set(pair.Key, pair.Value.Clone())
			}
		}
		return out
	}
	if left.Kind == NumberKind && right.Kind == NumberKind {
		lf, lerr := strconv.ParseFloat(left.Number, 64)
		rf, rerr := strconv.ParseFloat(right.Number, 64)
		if lerr == nil && rerr == nil {
			return NumberValue(formatFloat(lf * rf))
		}
	}
	return right.Clone()
}

func formatFloat(v float64) string {
	return strconv.FormatFloat(v, 'f', -1, 64)
}

func parseLooseScalar(raw string) *Value {
	switch raw {
	case "null", "~":
		return NullValue()
	case "true":
		return BoolValue(true)
	case "false":
		return BoolValue(false)
	}
	if len(raw) >= 2 && raw[0] == '"' && raw[len(raw)-1] == '"' {
		unquoted, err := strconv.Unquote(raw)
		if err == nil {
			return QuotedStringValue(unquoted)
		}
	}
	if len(raw) >= 2 && raw[0] == '\'' && raw[len(raw)-1] == '\'' {
		return QuotedStringValue(strings.ReplaceAll(raw[1:len(raw)-1], "''", "'"))
	}
	if isNumberLiteral(raw) {
		return NumberValue(raw)
	}
	return StringValue(raw)
}

func isNumberLiteral(raw string) bool {
	if raw == "" {
		return false
	}
	if raw[0] == '+' || raw[0] == '-' {
		raw = raw[1:]
	}
	if raw == "" {
		return false
	}
	dot := 0
	for _, r := range raw {
		switch {
		case r >= '0' && r <= '9':
		case r == '.':
			dot++
			if dot > 1 {
				return false
			}
		default:
			return false
		}
	}
	return true
}

func ParseJSONValue(data []byte) (*Value, error) {
	dec := json.NewDecoder(strings.NewReader(string(data)))
	dec.UseNumber()
	value, err := parseJSONToken(dec)
	if err != nil {
		return nil, err
	}
	return value, nil
}

func parseJSONToken(dec *json.Decoder) (*Value, error) {
	token, err := dec.Token()
	if err != nil {
		return nil, err
	}
	switch tok := token.(type) {
	case json.Delim:
		switch tok {
		case '{':
			obj := newObject()
			for dec.More() {
				keyTok, err := dec.Token()
				if err != nil {
					return nil, err
				}
				key, ok := keyTok.(string)
				if !ok {
					return nil, fmt.Errorf("invalid json object key")
				}
				val, err := parseJSONToken(dec)
				if err != nil {
					return nil, err
				}
				obj.Set(key, val)
			}
			if _, err := dec.Token(); err != nil {
				return nil, err
			}
			return ObjectValue(obj), nil
		case '[':
			items := []*Value{}
			for dec.More() {
				val, err := parseJSONToken(dec)
				if err != nil {
					return nil, err
				}
				items = append(items, val)
			}
			if _, err := dec.Token(); err != nil {
				return nil, err
			}
			return ArrayValue(items), nil
		default:
			return nil, fmt.Errorf("unexpected json delimiter %q", string(tok))
		}
	case nil:
		return NullValue(), nil
	case bool:
		return BoolValue(tok), nil
	case string:
		return StringValue(tok), nil
	case json.Number:
		return NumberValue(tok.String()), nil
	case float64:
		return NumberValue(formatFloat(tok)), nil
	default:
		return nil, fmt.Errorf("unsupported json token %T", token)
	}
}

func WriteJSON(w io.StringWriter, v *Value, pretty bool, level int, indent int) error {
	if v == nil {
		v = NullValue()
	}
	if pretty {
		return writeJSONPretty(w, v, level, indent)
	}
	return writeJSONCompact(w, v)
}

func writeJSONCompact(w io.StringWriter, v *Value) error {
	switch v.Kind {
	case NullKind:
		_, _ = w.WriteString("null")
	case BoolKind:
		if v.Bool {
			_, _ = w.WriteString("true")
		} else {
			_, _ = w.WriteString("false")
		}
	case NumberKind:
		_, _ = w.WriteString(v.Number)
	case StringKind:
		_, _ = w.WriteString(strconv.Quote(v.String))
	case ArrayKind:
		_, _ = w.WriteString("[")
		for i, item := range v.Array {
			if i > 0 {
				_, _ = w.WriteString(",")
			}
			if err := writeJSONCompact(w, item); err != nil {
				return err
			}
		}
		_, _ = w.WriteString("]")
	case ObjectKind:
		_, _ = w.WriteString("{")
		for i, pair := range v.Object.Pairs {
			if i > 0 {
				_, _ = w.WriteString(",")
			}
			_, _ = w.WriteString(strconv.Quote(pair.Key))
			_, _ = w.WriteString(":")
			if err := writeJSONCompact(w, pair.Value); err != nil {
				return err
			}
		}
		_, _ = w.WriteString("}")
	}
	return nil
}

func writeJSONPretty(w io.StringWriter, v *Value, level int, indent int) error {
	prefix := strings.Repeat(" ", level*indent)
	childPrefix := strings.Repeat(" ", (level+1)*indent)
	switch v.Kind {
	case NullKind, BoolKind, NumberKind, StringKind:
		return writeJSONCompact(w, v)
	case ArrayKind:
		if len(v.Array) == 0 {
			_, _ = w.WriteString("[]")
			return nil
		}
		_, _ = w.WriteString("[\n")
		for i, item := range v.Array {
			if i > 0 {
				_, _ = w.WriteString(",\n")
			}
			_, _ = w.WriteString(childPrefix)
			if err := writeJSONPretty(w, item, level+1, indent); err != nil {
				return err
			}
		}
		_, _ = w.WriteString("\n")
		_, _ = w.WriteString(prefix)
		_, _ = w.WriteString("]")
	case ObjectKind:
		if len(v.Object.Pairs) == 0 {
			_, _ = w.WriteString("{}")
			return nil
		}
		_, _ = w.WriteString("{\n")
		for i, pair := range v.Object.Pairs {
			if i > 0 {
				_, _ = w.WriteString(",\n")
			}
			_, _ = w.WriteString(childPrefix)
			_, _ = w.WriteString(strconv.Quote(pair.Key))
			_, _ = w.WriteString(": ")
			if err := writeJSONPretty(w, pair.Value, level+1, indent); err != nil {
				return err
			}
		}
		_, _ = w.WriteString("\n")
		_, _ = w.WriteString(prefix)
		_, _ = w.WriteString("}")
	}
	return nil
}

