package main

import (
	"fmt"
	"strconv"
	"strings"
)

type yamlLine struct {
	indent int
	text   string
	lineNo int
}

func ParseYAMLDocuments(data string) ([]*Value, error) {
	parts := splitYAMLDocuments(data)
	if len(parts) == 0 {
		return nil, nil
	}
	docs := make([]*Value, 0, len(parts))
	for _, part := range parts {
		lines := tokenizeYAML(part)
		if len(lines) == 0 {
			continue
		}
		pos := 0
		value, err := parseYAMLBlock(lines, &pos, lines[0].indent)
		if err != nil {
			return nil, err
		}
		docs = append(docs, value)
	}
	return docs, nil
}

func splitYAMLDocuments(data string) []string {
	if data == "" {
		return nil
	}
	lines := strings.Split(data, "\n")
	parts := []string{}
	current := []string{}
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "---" {
			if len(current) > 0 {
				parts = append(parts, strings.Join(current, "\n"))
				current = nil
			}
			continue
		}
		current = append(current, line)
	}
	if len(current) > 0 {
		parts = append(parts, strings.Join(current, "\n"))
	}
	return parts
}

func tokenizeYAML(doc string) []yamlLine {
	lines := []yamlLine{}
	for idx, raw := range strings.Split(doc, "\n") {
		line := strings.TrimRight(raw, " \t\r")
		if strings.TrimSpace(line) == "" {
			continue
		}
		if strings.HasPrefix(strings.TrimSpace(line), "#") {
			continue
		}
		indent := 0
		for indent < len(line) && line[indent] == ' ' {
			indent++
		}
		lines = append(lines, yamlLine{
			indent: indent,
			text:   stripInlineComment(line[indent:]),
			lineNo: idx + 1,
		})
	}
	return lines
}

func stripInlineComment(line string) string {
	if line == "" {
		return line
	}
	inSingle := false
	inDouble := false
	for i := 0; i < len(line); i++ {
		switch line[i] {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle && (i == 0 || line[i-1] != '\\') {
				inDouble = !inDouble
			}
		case '#':
			if !inSingle && !inDouble && (i == 0 || line[i-1] == ' ') {
				return strings.TrimRight(line[:i], " ")
			}
		}
	}
	return line
}

func parseYAMLBlock(lines []yamlLine, pos *int, indent int) (*Value, error) {
	if *pos >= len(lines) {
		return NullValue(), nil
	}
	if lines[*pos].indent < indent {
		return NullValue(), nil
	}
	if lines[*pos].indent != indent {
		indent = lines[*pos].indent
	}
	if isSeqLine(lines[*pos].text) {
		return parseYAMLSequence(lines, pos, indent)
	}
	return parseYAMLMapping(lines, pos, indent)
}

func isSeqLine(text string) bool {
	return text == "-" || strings.HasPrefix(text, "- ")
}

func parseYAMLSequence(lines []yamlLine, pos *int, indent int) (*Value, error) {
	items := []*Value{}
	for *pos < len(lines) && lines[*pos].indent == indent && isSeqLine(lines[*pos].text) {
		line := lines[*pos]
		rest := strings.TrimSpace(strings.TrimPrefix(line.text, "-"))
		start := *pos + 1
		end := start
		for end < len(lines) && lines[end].indent > indent {
			end++
		}
		item, err := parseSyntheticBlock(indent+2, rest, line.lineNo, lines[start:end])
		if err != nil {
			return nil, err
		}
		items = append(items, item)
		*pos = end
	}
	return ArrayValue(items), nil
}

func parseSyntheticBlock(indent int, first string, lineNo int, tail []yamlLine) (*Value, error) {
	synthetic := make([]yamlLine, 0, len(tail)+1)
	if first != "" {
		synthetic = append(synthetic, yamlLine{indent: indent, text: first, lineNo: lineNo})
	}
	synthetic = append(synthetic, tail...)
	if len(synthetic) == 0 {
		return NullValue(), nil
	}
	pos := 0
	return parseYAMLBlock(synthetic, &pos, indent)
}

func parseYAMLMapping(lines []yamlLine, pos *int, indent int) (*Value, error) {
	obj := newObject()
	for *pos < len(lines) && lines[*pos].indent == indent && !isSeqLine(lines[*pos].text) {
		line := lines[*pos]
		key, rest, ok := splitMapEntry(line.text)
		if !ok {
			return nil, fmt.Errorf("yaml: invalid mapping at line %d", line.lineNo)
		}
		*pos++
		if rest == "" {
			if *pos < len(lines) && lines[*pos].indent > indent {
				val, err := parseYAMLBlock(lines, pos, lines[*pos].indent)
				if err != nil {
					return nil, err
				}
				obj.Set(key, val)
			} else {
				obj.Set(key, NullValue())
			}
			continue
		}
		if strings.HasPrefix(rest, "[") || strings.HasPrefix(rest, "{") {
			val, err := parseFlowYAML(rest)
			if err != nil {
				return nil, err
			}
			obj.Set(key, val)
			continue
		}
		obj.Set(key, parseLooseScalar(rest))
	}
	return ObjectValue(obj), nil
}

func splitMapEntry(text string) (string, string, bool) {
	inSingle := false
	inDouble := false
	for i := 0; i < len(text); i++ {
		switch text[i] {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle && (i == 0 || text[i-1] != '\\') {
				inDouble = !inDouble
			}
		case ':':
			if !inSingle && !inDouble {
				key := strings.TrimSpace(text[:i])
				rest := strings.TrimSpace(text[i+1:])
				return key, rest, true
			}
		}
	}
	return "", "", false
}

func parseFlowYAML(text string) (*Value, error) {
	parser := &flowParser{text: text}
	return parser.parse()
}

type flowParser struct {
	text string
	pos  int
}

func (p *flowParser) parse() (*Value, error) {
	p.skipSpaces()
	if p.pos >= len(p.text) {
		return NullValue(), nil
	}
	switch p.text[p.pos] {
	case '[':
		return p.parseArray()
	case '{':
		return p.parseObject()
	default:
		return nil, fmt.Errorf("yaml: unsupported flow value")
	}
}

func (p *flowParser) parseArray() (*Value, error) {
	p.pos++
	items := []*Value{}
	for {
		p.skipSpaces()
		if p.pos >= len(p.text) {
			return nil, fmt.Errorf("yaml: while parsing a flow sequence: did not find expected ',' or ']'")
		}
		if p.text[p.pos] == ']' {
			p.pos++
			return ArrayValue(items), nil
		}
		val, err := p.parseScalarOrNested()
		if err != nil {
			return nil, err
		}
		items = append(items, val)
		p.skipSpaces()
		if p.pos >= len(p.text) {
			return nil, fmt.Errorf("yaml: while parsing a flow sequence: did not find expected ',' or ']'")
		}
		if p.text[p.pos] == ',' {
			p.pos++
			continue
		}
		if p.text[p.pos] == ']' {
			p.pos++
			return ArrayValue(items), nil
		}
		return nil, fmt.Errorf("yaml: while parsing a flow sequence: did not find expected ',' or ']'")
	}
}

func (p *flowParser) parseObject() (*Value, error) {
	p.pos++
	obj := newObject()
	for {
		p.skipSpaces()
		if p.pos >= len(p.text) {
			return nil, fmt.Errorf("yaml: while parsing a flow mapping: did not find expected ',' or '}'")
		}
		if p.text[p.pos] == '}' {
			p.pos++
			return ObjectValue(obj), nil
		}
		key := p.readBareToken()
		p.skipSpaces()
		if p.pos >= len(p.text) || p.text[p.pos] != ':' {
			return nil, fmt.Errorf("yaml: while parsing a flow mapping: did not find expected ':'")
		}
		p.pos++
		p.skipSpaces()
		val, err := p.parseScalarOrNested()
		if err != nil {
			return nil, err
		}
		obj.Set(key, val)
		p.skipSpaces()
		if p.pos >= len(p.text) {
			return nil, fmt.Errorf("yaml: while parsing a flow mapping: did not find expected ',' or '}'")
		}
		if p.text[p.pos] == ',' {
			p.pos++
			continue
		}
		if p.text[p.pos] == '}' {
			p.pos++
			return ObjectValue(obj), nil
		}
		return nil, fmt.Errorf("yaml: while parsing a flow mapping: did not find expected ',' or '}'")
	}
}

func (p *flowParser) parseScalarOrNested() (*Value, error) {
	p.skipSpaces()
	if p.pos >= len(p.text) {
		return NullValue(), nil
	}
	switch p.text[p.pos] {
	case '[':
		return p.parseArray()
	case '{':
		return p.parseObject()
	case '"':
		start := p.pos
		p.pos++
		escaped := false
		for p.pos < len(p.text) {
			ch := p.text[p.pos]
			p.pos++
			if ch == '"' && !escaped {
				break
			}
			escaped = ch == '\\' && !escaped
			if ch != '\\' {
				escaped = false
			}
		}
		raw := p.text[start:p.pos]
		unquoted, err := strconv.Unquote(raw)
		if err != nil {
			return nil, err
		}
		return QuotedStringValue(unquoted), nil
	default:
		token := p.readBareToken()
		return parseLooseScalar(token), nil
	}
}

func (p *flowParser) readBareToken() string {
	start := p.pos
	for p.pos < len(p.text) {
		switch p.text[p.pos] {
		case ' ', '\t', '\n', '\r', ',', ']', '}', ':':
			return strings.TrimSpace(p.text[start:p.pos])
		default:
			p.pos++
		}
	}
	return strings.TrimSpace(p.text[start:p.pos])
}

func (p *flowParser) skipSpaces() {
	for p.pos < len(p.text) {
		switch p.text[p.pos] {
		case ' ', '\t', '\n', '\r':
			p.pos++
		default:
			return
		}
	}
}

func RenderYAMLDocument(v *Value, indent int, pretty bool, unwrapScalar bool) string {
	if v == nil {
		v = NullValue()
	}
	if isScalar(v) {
		if unwrapScalar {
			return renderUnwrappedScalar(v) + "\n"
		}
		return renderYAMLScalar(v, pretty, true) + "\n"
	}
	var b strings.Builder
	writeYAMLBlock(&b, v, 0, indent, pretty)
	return b.String()
}

func writeYAMLBlock(b *strings.Builder, v *Value, level int, indent int, pretty bool) {
	prefix := strings.Repeat(" ", level*indent)
	switch v.Kind {
	case ObjectKind:
		if len(v.Object.Pairs) == 0 {
			b.WriteString("{}\n")
			return
		}
		for _, pair := range v.Object.Pairs {
			b.WriteString(prefix)
			b.WriteString(pair.Key)
			if isScalar(pair.Value) || isEmptyCollection(pair.Value) {
				b.WriteString(": ")
				b.WriteString(renderYAMLScalar(pair.Value, pretty, false))
				b.WriteString("\n")
				continue
			}
			b.WriteString(":\n")
			writeYAMLBlock(b, pair.Value, level+1, indent, pretty)
		}
	case ArrayKind:
		if len(v.Array) == 0 {
			b.WriteString("[]\n")
			return
		}
		for _, item := range v.Array {
			b.WriteString(prefix)
			b.WriteString("-")
			switch {
			case isScalar(item) || isEmptyCollection(item):
				b.WriteString(" ")
				b.WriteString(renderYAMLScalar(item, pretty, false))
				b.WriteString("\n")
			case item.Kind == ObjectKind && len(item.Object.Pairs) > 0:
				first := item.Object.Pairs[0]
				b.WriteString(" ")
				b.WriteString(first.Key)
				if isScalar(first.Value) || isEmptyCollection(first.Value) {
					b.WriteString(": ")
					b.WriteString(renderYAMLScalar(first.Value, pretty, false))
					b.WriteString("\n")
				} else {
					b.WriteString(":\n")
					writeYAMLBlock(b, first.Value, level+2, indent, pretty)
				}
				for _, pair := range item.Object.Pairs[1:] {
					b.WriteString(strings.Repeat(" ", (level+1)*indent))
					b.WriteString(pair.Key)
					if isScalar(pair.Value) || isEmptyCollection(pair.Value) {
						b.WriteString(": ")
						b.WriteString(renderYAMLScalar(pair.Value, pretty, false))
						b.WriteString("\n")
					} else {
						b.WriteString(":\n")
						writeYAMLBlock(b, pair.Value, level+2, indent, pretty)
					}
				}
			default:
				b.WriteString("\n")
				writeYAMLBlock(b, item, level+1, indent, pretty)
			}
		}
	default:
		b.WriteString(prefix)
		b.WriteString(renderYAMLScalar(v, pretty, false))
		b.WriteString("\n")
	}
}

func isScalar(v *Value) bool {
	return v.Kind == NullKind || v.Kind == BoolKind || v.Kind == NumberKind || v.Kind == StringKind
}

func isEmptyCollection(v *Value) bool {
	return (v.Kind == ArrayKind && len(v.Array) == 0) || (v.Kind == ObjectKind && len(v.Object.Pairs) == 0)
}

func renderUnwrappedScalar(v *Value) string {
	switch v.Kind {
	case NullKind:
		return "null"
	case BoolKind:
		if v.Bool {
			return "true"
		}
		return "false"
	case NumberKind:
		return v.Number
	case StringKind:
		return v.String
	default:
		return ""
	}
}

func renderYAMLScalar(v *Value, pretty bool, standalone bool) string {
	switch v.Kind {
	case NullKind:
		return "null"
	case BoolKind:
		if v.Bool {
			return "true"
		}
		return "false"
	case NumberKind:
		return v.Number
	case StringKind:
		if pretty {
			return renderPlainString(v.String)
		}
		if v.Style == StyleDoubleQuoted {
			return strconv.Quote(v.String)
		}
		return renderPlainString(v.String)
	case ArrayKind:
		return "[]"
	case ObjectKind:
		return "{}"
	default:
		return ""
	}
}

func renderPlainString(s string) string {
	if s == "" {
		return `""`
	}
	if needsQuotedYAML(s) {
		return strconv.Quote(s)
	}
	return s
}

func needsQuotedYAML(s string) bool {
	switch s {
	case "null", "true", "false", "~":
		return true
	}
	if isNumberLiteral(s) {
		return true
	}
	if strings.HasPrefix(s, " ") || strings.HasSuffix(s, " ") {
		return true
	}
	if strings.ContainsAny(s, "[]{}#&*!|>'\"%@`") {
		return true
	}
	if strings.Contains(s, ": ") {
		return true
	}
	return false
}

