package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
	"unicode"
)

type Meta struct {
	FileIndex     int
	DocumentIndex int
	Filename      string
}

type EvalCtx struct {
	Current *Value
	Meta    Meta
	Vars    map[string]*Value
}

type Expr interface {
	Eval(stream []EvalCtx, rt *Runtime) ([]EvalCtx, error)
}

type Runtime struct {
	InputFormat   string
	DisableEnvOps bool
	DisableFileOps bool
}

type LiteralExpr struct {
	Value *Value
}

type IdentityExpr struct{}

type IdentExpr struct {
	Name string
}

type VarExpr struct {
	Name string
}

type PathExpr struct {
	Base     Expr
	Segments []PathSegment
}

type PathSegment struct {
	Kind  string
	Key   string
	Index int
}

type PipeExpr struct {
	Left  Expr
	Right Expr
}

type BinaryExpr struct {
	Op    string
	Left  Expr
	Right Expr
}

type AssignExpr struct {
	Target *PathExpr
	Value  Expr
}

type ArrayCollectExpr struct {
	Inner Expr
}

type FuncExpr struct {
	Name string
	Args []Expr
}

type IReduceExpr struct {
	Source  Expr
	VarName string
	Init    Expr
	Update  Expr
}

func (e *LiteralExpr) Eval(stream []EvalCtx, rt *Runtime) ([]EvalCtx, error) {
	out := make([]EvalCtx, 0, len(stream))
	for _, ctx := range stream {
		out = append(out, EvalCtx{Current: e.Value.Clone(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
	}
	if len(stream) == 0 {
		out = append(out, EvalCtx{Current: e.Value.Clone()})
	}
	return out, nil
}

func (e *IdentityExpr) Eval(stream []EvalCtx, rt *Runtime) ([]EvalCtx, error) {
	out := make([]EvalCtx, 0, len(stream))
	for _, ctx := range stream {
		out = append(out, EvalCtx{Current: ctx.Current.Clone(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
	}
	return out, nil
}

func (e *IdentExpr) Eval(stream []EvalCtx, rt *Runtime) ([]EvalCtx, error) {
	out := make([]EvalCtx, 0, len(stream))
	for _, ctx := range stream {
		switch e.Name {
		case "fileIndex", "fi":
			out = append(out, EvalCtx{Current: NumberValue(strconv.Itoa(ctx.Meta.FileIndex)), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
		case "documentIndex", "di":
			out = append(out, EvalCtx{Current: NumberValue(strconv.Itoa(ctx.Meta.DocumentIndex)), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
		case "filename":
			out = append(out, EvalCtx{Current: StringValue(ctx.Meta.Filename), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
		default:
			out = append(out, EvalCtx{Current: NullValue(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
		}
	}
	return out, nil
}

func (e *VarExpr) Eval(stream []EvalCtx, rt *Runtime) ([]EvalCtx, error) {
	out := make([]EvalCtx, 0, len(stream))
	for _, ctx := range stream {
		value, ok := ctx.Vars[e.Name]
		if !ok {
			value = NullValue()
		}
		out = append(out, EvalCtx{Current: value.Clone(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
	}
	return out, nil
}

func (e *PathExpr) Eval(stream []EvalCtx, rt *Runtime) ([]EvalCtx, error) {
	base := e.Base
	if base == nil {
		base = &IdentityExpr{}
	}
	baseResults, err := base.Eval(stream, rt)
	if err != nil {
		return nil, err
	}
	current := baseResults
	for _, segment := range e.Segments {
		next := []EvalCtx{}
		for _, ctx := range current {
			switch segment.Kind {
			case "field":
				if ctx.Current.Kind == ObjectKind {
					if val, ok := ctx.Current.Object.Get(segment.Key); ok {
						next = append(next, EvalCtx{Current: val.Clone(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
						continue
					}
				}
				next = append(next, EvalCtx{Current: NullValue(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
			case "index":
				if ctx.Current.Kind == ArrayKind && segment.Index >= 0 && segment.Index < len(ctx.Current.Array) {
					next = append(next, EvalCtx{Current: ctx.Current.Array[segment.Index].Clone(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
					continue
				}
				next = append(next, EvalCtx{Current: NullValue(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
			case "iterate":
				switch ctx.Current.Kind {
				case ArrayKind:
					for _, item := range ctx.Current.Array {
						next = append(next, EvalCtx{Current: item.Clone(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
					}
				case ObjectKind:
					for _, pair := range ctx.Current.Object.Pairs {
						next = append(next, EvalCtx{Current: pair.Value.Clone(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
					}
				}
			}
		}
		current = next
	}
	return current, nil
}

func (e *PipeExpr) Eval(stream []EvalCtx, rt *Runtime) ([]EvalCtx, error) {
	left, err := e.Left.Eval(stream, rt)
	if err != nil {
		return nil, err
	}
	return e.Right.Eval(left, rt)
}

func (e *BinaryExpr) Eval(stream []EvalCtx, rt *Runtime) ([]EvalCtx, error) {
	if e.Op == "==" {
		out := make([]EvalCtx, 0, len(stream))
		for _, ctx := range stream {
			left, err := firstValue(e.Left, []EvalCtx{ctx}, rt)
			if err != nil {
				return nil, err
			}
			right, err := firstValue(e.Right, []EvalCtx{ctx}, rt)
			if err != nil {
				return nil, err
			}
			out = append(out, EvalCtx{Current: BoolValue(left.Equal(right)), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
		}
		return out, nil
	}
	if e.Op == "*" {
		ctx := pickContext(stream)
		left, err := firstValue(e.Left, stream, rt)
		if err != nil {
			return nil, err
		}
		right, err := firstValue(e.Right, stream, rt)
		if err != nil {
			return nil, err
		}
		return []EvalCtx{{Current: MergeValues(left, right), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)}}, nil
	}
	return nil, fmt.Errorf("unsupported operator %s", e.Op)
}

func (e *AssignExpr) Eval(stream []EvalCtx, rt *Runtime) ([]EvalCtx, error) {
	out := make([]EvalCtx, 0, len(stream))
	for _, ctx := range stream {
		root := ctx.Current.Clone()
		value, err := firstValue(e.Value, []EvalCtx{{Current: ctx.Current.Clone(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)}}, rt)
		if err != nil {
			return nil, err
		}
		if err := setPath(root, e.Target.Segments, value.Clone()); err != nil {
			return nil, err
		}
		out = append(out, EvalCtx{Current: root, Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
	}
	return out, nil
}

func (e *ArrayCollectExpr) Eval(stream []EvalCtx, rt *Runtime) ([]EvalCtx, error) {
	values, err := e.Inner.Eval(stream, rt)
	if err != nil {
		return nil, err
	}
	items := []*Value{}
	for _, value := range values {
		items = append(items, value.Current.Clone())
	}
	ctx := pickContext(stream)
	return []EvalCtx{{Current: ArrayValue(items), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)}}, nil
}

func (e *FuncExpr) Eval(stream []EvalCtx, rt *Runtime) ([]EvalCtx, error) {
	switch e.Name {
	case "select":
		if len(e.Args) != 1 {
			return nil, fmt.Errorf("select requires one argument")
		}
		out := []EvalCtx{}
		for _, ctx := range stream {
			value, err := firstValue(e.Args[0], []EvalCtx{ctx}, rt)
			if err != nil {
				return nil, err
			}
			if value.Truthy() {
				out = append(out, EvalCtx{Current: ctx.Current.Clone(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
			}
		}
		return out, nil
	case "strenv":
		if rt.DisableEnvOps {
			return nil, fmt.Errorf("env operations disabled")
		}
		name, err := resolveStringArgument(e.Args)
		if err != nil {
			return nil, err
		}
		value := os.Getenv(name)
		out := make([]EvalCtx, 0, len(stream))
		for _, ctx := range stream {
			out = append(out, EvalCtx{Current: StringValue(value), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
		}
		if len(stream) == 0 {
			out = append(out, EvalCtx{Current: StringValue(value)})
		}
		return out, nil
	case "load":
		if rt.DisableFileOps {
			return nil, fmt.Errorf("file operations disabled")
		}
		name, err := resolveStringArgument(e.Args)
		if err != nil {
			return nil, err
		}
		value, err := loadSingleValue(name, rt.InputFormat)
		if err != nil {
			return nil, err
		}
		out := make([]EvalCtx, 0, len(stream))
		for _, ctx := range stream {
			out = append(out, EvalCtx{Current: value.Clone(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
		}
		if len(stream) == 0 {
			out = append(out, EvalCtx{Current: value.Clone()})
		}
		return out, nil
	default:
		return nil, fmt.Errorf("unsupported function %s", e.Name)
	}
}

func (e *IReduceExpr) Eval(stream []EvalCtx, rt *Runtime) ([]EvalCtx, error) {
	source, err := e.Source.Eval(stream, rt)
	if err != nil {
		return nil, err
	}
	initCtx := pickContext(stream)
	acc, err := firstValue(e.Init, []EvalCtx{initCtx}, rt)
	if err != nil {
		return nil, err
	}
	current := acc.Clone()
	for _, item := range source {
		vars := cloneVars(initCtx.Vars)
		vars[e.VarName] = item.Current.Clone()
		next, err := firstValue(e.Update, []EvalCtx{{Current: current.Clone(), Meta: initCtx.Meta, Vars: vars}}, rt)
		if err != nil {
			return nil, err
		}
		current = next.Clone()
	}
	return []EvalCtx{{Current: current, Meta: initCtx.Meta, Vars: cloneVars(initCtx.Vars)}}, nil
}

func cloneVars(vars map[string]*Value) map[string]*Value {
	if len(vars) == 0 {
		return nil
	}
	out := make(map[string]*Value, len(vars))
	for key, value := range vars {
		out[key] = value.Clone()
	}
	return out
}

func firstValue(expr Expr, stream []EvalCtx, rt *Runtime) (*Value, error) {
	results, err := expr.Eval(stream, rt)
	if err != nil {
		return nil, err
	}
	if len(results) == 0 {
		return NullValue(), nil
	}
	return results[0].Current.Clone(), nil
}

func pickContext(stream []EvalCtx) EvalCtx {
	if len(stream) == 0 {
		return EvalCtx{Current: NullValue()}
	}
	ctx := stream[0]
	return EvalCtx{Current: ctx.Current.Clone(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)}
}

func resolveStringArgument(args []Expr) (string, error) {
	if len(args) != 1 {
		return "", fmt.Errorf("expected one argument")
	}
	switch arg := args[0].(type) {
	case *LiteralExpr:
		if arg.Value.Kind != StringKind {
			return "", fmt.Errorf("expected string argument")
		}
		return arg.Value.String, nil
	case *IdentExpr:
		return arg.Name, nil
	default:
		return "", fmt.Errorf("expected string argument")
	}
}

func setPath(root *Value, segments []PathSegment, value *Value) error {
	if root == nil {
		return fmt.Errorf("cannot set path on nil")
	}
	current := root
	for i, segment := range segments {
		last := i == len(segments)-1
		switch segment.Kind {
		case "field":
			if current.Kind == NullKind {
				current.Kind = ObjectKind
				current.Object = newObject()
			}
			if current.Kind != ObjectKind {
				current.Kind = ObjectKind
				current.Object = newObject()
				current.Array = nil
			}
			if last {
				current.Object.Set(segment.Key, value.Clone())
				continue
			}
			child, ok := current.Object.Get(segment.Key)
			if !ok {
				child = inferContainer(segments[i+1])
				current.Object.Set(segment.Key, child)
			}
			current = child
		case "index":
			if current.Kind == NullKind {
				current.Kind = ArrayKind
				current.Array = []*Value{}
			}
			if current.Kind != ArrayKind {
				current.Kind = ArrayKind
				current.Array = []*Value{}
				current.Object = nil
			}
			for len(current.Array) <= segment.Index {
				current.Array = append(current.Array, NullValue())
			}
			if last {
				current.Array[segment.Index] = value.Clone()
				continue
			}
			if current.Array[segment.Index] == nil || current.Array[segment.Index].Kind == NullKind {
				current.Array[segment.Index] = inferContainer(segments[i+1])
			}
			current = current.Array[segment.Index]
		default:
			return fmt.Errorf("unsupported assignment segment %s", segment.Kind)
		}
	}
	return nil
}

func inferContainer(next PathSegment) *Value {
	if next.Kind == "index" {
		return ArrayValue(nil)
	}
	return ObjectValue(newObject())
}

func ParseExpression(text string) (Expr, error) {
	tokens, err := tokenize(text)
	if err != nil {
		return nil, err
	}
	parser := &exprParser{tokens: tokens}
	expr, err := parser.parseExpr()
	if err != nil {
		return nil, err
	}
	if parser.peek().kind != tokEOF {
		return nil, fmt.Errorf("bad expression, unexpected token %q", parser.peek().text)
	}
	return expr, nil
}

type tokenKind int

const (
	tokEOF tokenKind = iota
	tokDot
	tokLBracket
	tokRBracket
	tokLParen
	tokRParen
	tokPipe
	tokStar
	tokAssign
	tokEqual
	tokComma
	tokSemicolon
	tokIdentifier
	tokVariable
	tokString
	tokNumber
)

type token struct {
	kind tokenKind
	text string
}

func tokenize(text string) ([]token, error) {
	out := []token{}
	for i := 0; i < len(text); {
		switch ch := text[i]; {
		case unicode.IsSpace(rune(ch)):
			i++
		case ch == '.':
			out = append(out, token{kind: tokDot, text: "."})
			i++
		case ch == '[':
			out = append(out, token{kind: tokLBracket, text: "["})
			i++
		case ch == ']':
			out = append(out, token{kind: tokRBracket, text: "]"})
			i++
		case ch == '(':
			out = append(out, token{kind: tokLParen, text: "("})
			i++
		case ch == ')':
			out = append(out, token{kind: tokRParen, text: ")"})
			i++
		case ch == '|':
			out = append(out, token{kind: tokPipe, text: "|"})
			i++
		case ch == '*':
			out = append(out, token{kind: tokStar, text: "*"})
			i++
		case ch == ';':
			out = append(out, token{kind: tokSemicolon, text: ";"})
			i++
		case ch == ',':
			out = append(out, token{kind: tokComma, text: ","})
			i++
		case ch == '=':
			if i+1 < len(text) && text[i+1] == '=' {
				out = append(out, token{kind: tokEqual, text: "=="})
				i += 2
			} else {
				out = append(out, token{kind: tokAssign, text: "="})
				i++
			}
		case ch == '$':
			start := i + 1
			i++
			for i < len(text) && isIdentChar(text[i]) {
				i++
			}
			out = append(out, token{kind: tokVariable, text: text[start:i]})
		case ch == '"' || ch == '\'':
			quote := ch
			start := i
			i++
			escaped := false
			for i < len(text) {
				if text[i] == quote && (!escaped || quote == '\'') {
					i++
					break
				}
				if quote == '"' && text[i] == '\\' && !escaped {
					escaped = true
				} else {
					escaped = false
				}
				i++
			}
			if i > len(text) {
				return nil, fmt.Errorf("bad expression, unterminated string")
			}
			out = append(out, token{kind: tokString, text: text[start:i]})
		case isDigit(ch) || (ch == '-' && i+1 < len(text) && isDigit(text[i+1])):
			start := i
			i++
			for i < len(text) && (isDigit(text[i]) || text[i] == '.') {
				i++
			}
			out = append(out, token{kind: tokNumber, text: text[start:i]})
		case isIdentStart(ch):
			start := i
			i++
			for i < len(text) && isIdentChar(text[i]) {
				i++
			}
			out = append(out, token{kind: tokIdentifier, text: text[start:i]})
		default:
			return nil, fmt.Errorf("bad expression, unexpected character %q", string(ch))
		}
	}
	out = append(out, token{kind: tokEOF})
	return out, nil
}

func isDigit(b byte) bool {
	return b >= '0' && b <= '9'
}

func isIdentStart(b byte) bool {
	return b == '_' || unicode.IsLetter(rune(b))
}

func isIdentChar(b byte) bool {
	return isIdentStart(b) || isDigit(b)
}

type exprParser struct {
	tokens []token
	pos    int
}

func (p *exprParser) parseExpr() (Expr, error) {
	return p.parsePipe()
}

func (p *exprParser) parsePipe() (Expr, error) {
	left, err := p.parseReduce()
	if err != nil {
		return nil, err
	}
	for p.match(tokPipe) {
		right, err := p.parseReduce()
		if err != nil {
			return nil, err
		}
		left = &PipeExpr{Left: left, Right: right}
	}
	return left, nil
}

func (p *exprParser) parseReduce() (Expr, error) {
	left, err := p.parseAssign()
	if err != nil {
		return nil, err
	}
	if p.peekIdentifier("as") {
		p.next()
		varTok := p.next()
		if varTok.kind != tokVariable {
			return nil, fmt.Errorf("bad expression, expected variable after as")
		}
		if !p.peekIdentifier("ireduce") {
			return nil, fmt.Errorf("bad expression, expected ireduce")
		}
		p.next()
		if !p.match(tokLParen) {
			return nil, fmt.Errorf("bad expression, expected (")
		}
		initExpr, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if !p.match(tokSemicolon) {
			return nil, fmt.Errorf("bad expression, expected ;")
		}
		updateExpr, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if !p.match(tokRParen) {
			return nil, fmt.Errorf("bad expression, expected )")
		}
		return &IReduceExpr{
			Source:  left,
			VarName: varTok.text,
			Init:    initExpr,
			Update:  updateExpr,
		}, nil
	}
	return left, nil
}

func (p *exprParser) parseAssign() (Expr, error) {
	left, err := p.parseEquality()
	if err != nil {
		return nil, err
	}
	if p.match(tokAssign) {
		right, err := p.parseAssign()
		if err != nil {
			return nil, err
		}
		path, ok := left.(*PathExpr)
		if !ok {
			return nil, fmt.Errorf("bad expression, assignment target must be a path")
		}
		return &AssignExpr{Target: path, Value: right}, nil
	}
	return left, nil
}

func (p *exprParser) parseEquality() (Expr, error) {
	left, err := p.parseMultiply()
	if err != nil {
		return nil, err
	}
	for p.match(tokEqual) {
		right, err := p.parseMultiply()
		if err != nil {
			return nil, err
		}
		left = &BinaryExpr{Op: "==", Left: left, Right: right}
	}
	return left, nil
}

func (p *exprParser) parseMultiply() (Expr, error) {
	left, err := p.parsePostfix()
	if err != nil {
		return nil, err
	}
	for p.match(tokStar) {
		right, err := p.parsePostfix()
		if err != nil {
			return nil, err
		}
		left = &BinaryExpr{Op: "*", Left: left, Right: right}
	}
	return left, nil
}

func (p *exprParser) parsePostfix() (Expr, error) {
	base, err := p.parsePrimary()
	if err != nil {
		return nil, err
	}
	segments := []PathSegment{}
	for {
		switch {
		case p.match(tokDot):
			if p.peek().kind == tokIdentifier {
				name := p.next().text
				segments = append(segments, PathSegment{Kind: "field", Key: name})
				continue
			}
			if len(segments) == 0 {
				if _, ok := base.(*IdentityExpr); ok {
					continue
				}
			}
			return nil, fmt.Errorf("bad expression, expected field after .")
		case p.match(tokLBracket):
			if p.match(tokRBracket) {
				segments = append(segments, PathSegment{Kind: "iterate"})
				continue
			}
			numberTok := p.next()
			if numberTok.kind != tokNumber {
				return nil, fmt.Errorf("bad expression, expected numeric index")
			}
			index, err := strconv.Atoi(numberTok.text)
			if err != nil {
				return nil, err
			}
			if !p.match(tokRBracket) {
				return nil, fmt.Errorf("bad expression, could not find matching `]`")
			}
			segments = append(segments, PathSegment{Kind: "index", Index: index})
		default:
			if len(segments) > 0 {
				return &PathExpr{Base: base, Segments: segments}, nil
			}
			return base, nil
		}
	}
}

func (p *exprParser) parsePrimary() (Expr, error) {
	tok := p.next()
	switch tok.kind {
	case tokDot:
		p.pos--
		return &PathExpr{Base: &IdentityExpr{}}, nil
	case tokString:
		value, err := parseStringToken(tok.text)
		if err != nil {
			return nil, err
		}
		return &LiteralExpr{Value: value}, nil
	case tokNumber:
		return &LiteralExpr{Value: NumberValue(tok.text)}, nil
	case tokIdentifier:
		switch tok.text {
		case "true":
			return &LiteralExpr{Value: BoolValue(true)}, nil
		case "false":
			return &LiteralExpr{Value: BoolValue(false)}, nil
		case "null":
			return &LiteralExpr{Value: NullValue()}, nil
		}
		if p.match(tokLParen) {
			args := []Expr{}
			if !p.match(tokRParen) {
				for {
					arg, err := p.parseExpr()
					if err != nil {
						return nil, err
					}
					args = append(args, arg)
					if p.match(tokComma) {
						continue
					}
					if !p.match(tokRParen) {
						return nil, fmt.Errorf("bad expression, expected )")
					}
					break
				}
			}
			return &FuncExpr{Name: tok.text, Args: args}, nil
		}
		return &IdentExpr{Name: tok.text}, nil
	case tokVariable:
		return &VarExpr{Name: tok.text}, nil
	case tokLParen:
		expr, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if !p.match(tokRParen) {
			return nil, fmt.Errorf("bad expression, expected )")
		}
		return expr, nil
	case tokLBracket:
		expr, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if !p.match(tokRBracket) {
			return nil, fmt.Errorf("bad expression, could not find matching `]`")
		}
		return &ArrayCollectExpr{Inner: expr}, nil
	default:
		return nil, fmt.Errorf("bad expression, unexpected token %q", tok.text)
	}
}

func parseStringToken(raw string) (*Value, error) {
	if strings.HasPrefix(raw, "\"") {
		value, err := strconv.Unquote(raw)
		if err != nil {
			return nil, err
		}
		return QuotedStringValue(value), nil
	}
	if strings.HasPrefix(raw, "'") {
		return QuotedStringValue(strings.ReplaceAll(raw[1:len(raw)-1], "''", "'")), nil
	}
	return StringValue(raw), nil
}

func (p *exprParser) match(kind tokenKind) bool {
	if p.peek().kind == kind {
		p.pos++
		return true
	}
	return false
}

func (p *exprParser) peekIdentifier(name string) bool {
	return p.peek().kind == tokIdentifier && p.peek().text == name
}

func (p *exprParser) peek() token {
	if p.pos >= len(p.tokens) {
		return token{kind: tokEOF}
	}
	return p.tokens[p.pos]
}

func (p *exprParser) next() token {
	tok := p.peek()
	if p.pos < len(p.tokens) {
		p.pos++
	}
	return tok
}

