+		value, err := parseProperties(string(data))
+		if err != nil {
+			return nil, err
+		}
+		return []*Value{value}, nil
+	case "ini":
+		value, err := parseINI(string(data))
+		if err != nil {
+			return nil, err
+		}
+		return []*Value{value}, nil
+	case "base64":
+		decoded, err := base64.StdEncoding.DecodeString(strings.TrimSpace(string(data)))
+		if err != nil {
+			return nil, fmt.Errorf("bad file '%s': %v", sourceName, err)
+		}
+		return []*Value{StringValue(string(decoded))}, nil
+	case "uri":
+		decoded, err := url.QueryUnescape(strings.TrimSpace(string(data)))
+		if err != nil {
+			return nil, fmt.Errorf("bad file '%s': %v", sourceName, err)
+		}
+		return []*Value{StringValue(decoded)}, nil
+	case "toml", "hcl", "lua":
+		return nil, fmt.Errorf("bad file '%s': unsupported %s parsing", sourceName, format)
+	default:
+		return nil, fmt.Errorf("bad file '%s': unsupported format %s", sourceName, format)
+	}
+}
+
+func loadSingleValue(path string, preferredFormat string) (*Value, error) {
+	data, err := os.ReadFile(path)
+	if err != nil {
+		return nil, err
+	}
+	format := preferredFormat
+	if format == "" || format == "auto" {
+		format = detectInputFormat(path)
+	}
+	values, err := parseDocuments(data, format, path)
+	if err != nil {
+		return nil, err
+	}
+	if len(values) == 0 {
+		return NullValue(), nil
+	}
+	return values[0], nil
+}
+
+func renderValue(v *Value, format string, pretty bool, indent int, unwrapScalar bool, shellSep string, propSep string) (string, error) {
+	switch format {
+	case "yaml":
+		return RenderYAMLDocument(v, indent, pretty, unwrapScalar), nil
+	case "json":
+		var b strings.Builder
+		if err := WriteJSON(&b, v, true, 0, indent); err != nil {
+			return "", err
+		}
+		b.WriteString("\n")
+		return b.String(), nil
+	case "xml":
+		return renderXML(v), nil
+	case "csv":
+		return renderCSV(v, ',')
+	case "tsv":
+		return renderCSV(v, '\t')
+	case "props":
+		return renderProperties(v, ".", propSep), nil
+	case "shell":
+		return renderProperties(v, shellSep, "="), nil
+	case "lua":
+		return renderLua(v), nil
+	case "ini":
+		return renderINI(v), nil
+	case "base64":
+		return base64.StdEncoding.EncodeToString([]byte(stringifyScalar(v))) + "\n", nil
+	case "uri":
+		return url.QueryEscape(stringifyScalar(v)) + "\n", nil
+	case "toml":
+		return renderTOML(v), nil
+	case "hcl":
+		return renderHCL(v), nil
+	default:
+		return "", fmt.Errorf("unsupported output format %s", format)
+	}
+}
+
+func stringifyScalar(v *Value) string {
+	if v == nil {
+		return "null"
+	}
+	switch v.Kind {
+	case NullKind:
+		return "null"
+	case BoolKind:
+		if v.Bool {
+			return "true"
+		}
+		return "false"
+	case NumberKind:
+		return v.Number
+	case StringKind:
+		return v.String
+	default:
+		var b strings.Builder
+		_ = WriteJSON(&b, v, false, 0, 2)
+		return b.String()
+	}
+}
+
+type xmlElement struct {
+	Name     string
+	Attrs    []xml.Attr
+	Children []*xmlElement
+	Text     string
+}
+
+func parseXML(data []byte) (*Value, error) {
+	dec := xml.NewDecoder(bytes.NewReader(data))
+	stack := []*xmlElement{}
+	var roots []*xmlElement
+	for {
+		tok, err := dec.Token()
+		if err == io.EOF {
+			break
+		}
+		if err != nil {
+			return nil, err
+		}
+		switch node := tok.(type) {
+		case xml.StartElement:
+			el := &xmlElement{Name: node.Name.Local, Attrs: node.Attr}
+			stack = append(stack, el)
+		case xml.CharData:
+			if len(stack) == 0 {
+				continue
+			}
+			text := strings.TrimSpace(string(node))
+			if text != "" {
+				stack[len(stack)-1].Text += text
+			}
+		case xml.EndElement:
+			if len(stack) == 0 {
+				continue
+			}
+			done := stack[len(stack)-1]
+			stack = stack[:len(stack)-1]
+			if len(stack) == 0 {
+				roots = append(roots, done)
+			} else {
+				parent := stack[len(stack)-1]
+				parent.Children = append(parent.Children, done)
+			}
+		}
+	}
+	rootObj := newObject()
+	for _, root := range roots {
+		rootObj.Set(root.Name, convertXMLNode(root))
+	}
+	return ObjectValue(rootObj), nil
+}
+
+func convertXMLNode(node *xmlElement) *Value {
+	hasAttrs := len(node.Attrs) > 0
+	hasChildren := len(node.Children) > 0
+	text := node.Text
+	if !hasAttrs && !hasChildren {
+		return StringValue(text)
+	}
+	obj := newObject()
+	for _, attr := range node.Attrs {
+		obj.Set("+@"+attr.Name.Local, StringValue(attr.Value))
+	}
+	if text != "" {
+		obj.Set("+content", StringValue(text))
+	}
+	grouped := map[string][]*xmlElement{}
+	order := []string{}
+	for _, child := range node.Children {
+		if _, ok := grouped[child.Name]; !ok {
+			order = append(order, child.Name)
+		}
+		grouped[child.Name] = append(grouped[child.Name], child)
+	}
+	for _, name := range order {
+		children := grouped[name]
+		if len(children) == 1 {
+			obj.Set(name, convertXMLNode(children[0]))
+		} else {
+			items := []*Value{}
+			for _, child := range children {
+				items = append(items, convertXMLNode(child))
+			}
+			obj.Set(name, ArrayValue(items))
+		}
+	}
+	return ObjectValue(obj)
+}
+
+func renderXML(v *Value) string {
+	var b strings.Builder
+	switch v.Kind {
+	case ObjectKind:
+		for _, pair := range v.Object.Pairs {
+			writeXMLElement(&b, pair.Key, pair.Value, 0)
+		}
+	default:
+		writeXMLElement(&b, "value", v, 0)
+	}
+	return b.String()
+}
+
+func writeXMLElement(b *strings.Builder, name string, v *Value, level int) {
+	if v.Kind == ArrayKind {
+		for _, item := range v.Array {
+			writeXMLElement(b, name, item, level)
+		}
+		return
+	}
+	indent := strings.Repeat("  ", level)
+	switch v.Kind {
+	case ObjectKind:
+		attrs := []string{}
+		children := []Pair{}
+		content := ""
+		for _, pair := range v.Object.Pairs {
+			switch {
+			case strings.HasPrefix(pair.Key, "+@"):
+				attrs = append(attrs, fmt.Sprintf(` %s="%s"`, strings.TrimPrefix(pair.Key, "+@"), escapeXMLText(stringifyScalar(pair.Value))))
+			case pair.Key == "+content":
+				content = escapeXMLText(stringifyScalar(pair.Value))
+			default:
+				children = append(children, pair)
+			}
+		}
+		sort.Strings(attrs)
+		if len(children) == 0 {
+			b.WriteString(indent)
+			b.WriteString("<")
+			b.WriteString(name)
+			for _, attr := range attrs {
+				b.WriteString(attr)
+			}
+			b.WriteString(">")
+			b.WriteString(content)
+			b.WriteString("</")
+			b.WriteString(name)
+			b.WriteString(">\n")
+			return
+		}
+		b.WriteString(indent)
+		b.WriteString("<")
+		b.WriteString(name)
+		for _, attr := range attrs {
+			b.WriteString(attr)
+		}
+		b.WriteString(">\n")
+		for _, child := range children {
+			writeXMLElement(b, child.Key, child.Value, level+1)
+		}
+		b.WriteString(indent)
+		b.WriteString("</")
+		b.WriteString(name)
+		b.WriteString(">\n")
+	default:
+		b.WriteString(indent)
+		b.WriteString("<")
+		b.WriteString(name)
+		b.WriteString(">")
+		b.WriteString(escapeXMLText(stringifyScalar(v)))
+		b.WriteString("</")
+		b.WriteString(name)
+		b.WriteString(">\n")
+	}
+}
+
+func escapeXMLText(s string) string {
+	replacer := strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;", `"`, "&quot;")
+	return replacer.Replace(s)
+}
+
+func parseCSV(data []byte, sep rune) (*Value, error) {
+	r := csv.NewReader(bytes.NewReader(data))
+	r.Comma = sep
+	rows, err := r.ReadAll()
+	if err != nil {
+		return nil, err
+	}
+	if len(rows) == 0 {
+		return ArrayValue(nil), nil
+	}
+	headers := rows[0]
+	items := []*Value{}
+	for _, row := range rows[1:] {
+		obj := newObject()
+		for i, header := range headers {
+			cell := ""
+			if i < len(row) {
+				cell = row[i]
+			}
+			obj.Set(header, parseLooseScalar(cell))
+		}
+		items = append(items, ObjectValue(obj))
+	}
+	return ArrayValue(items), nil
+}
+
+func renderCSV(v *Value, sep rune) (string, error) {
+	if v.Kind != ArrayKind {
+		return "", fmt.Errorf("csv output requires an array of objects")
+	}
+	headers := []string{}
+	seen := map[string]bool{}
+	for _, item := range v.Array {
+		if item.Kind != ObjectKind {
+			continue
+		}
+		for _, pair := range item.Object.Pairs {
+			if !seen[pair.Key] {
+				seen[pair.Key] = true
+				headers = append(headers, pair.Key)
+			}
+		}
+	}
+	var b strings.Builder
+	w := csv.NewWriter(&b)
+	w.Comma = sep
+	if err := w.Write(headers); err != nil {
+		return "", err
+	}
+	for _, item := range v.Array {
+		record := make([]string, 0, len(headers))
+		for _, header := range headers {
+			if item.Kind == ObjectKind {
+				if value, ok := item.Object.Get(header); ok {
+					record = append(record, stringifyScalar(value))
+					continue
+				}
+			}
+			record = append(record, "")
+		}
+		if err := w.Write(record); err != nil {
+			return "", err
+		}
+	}
+	w.Flush()
+	if err := w.Error(); err != nil {
+		return "", err
+	}
+	return b.String(), nil
+}
+
+func parseProperties(data string) (*Value, error) {
+	root := ObjectValue(newObject())
+	for _, line := range strings.Split(data, "\n") {
+		line = strings.TrimSpace(line)
+		if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, ";") {
+			continue
+		}
+		parts := strings.SplitN(line, "=", 2)
+		if len(parts) != 2 {
+			parts = strings.SplitN(line, ":", 2)
+			if len(parts) != 2 {
+				continue
+			}
+		}
+		key := strings.TrimSpace(parts[0])
+		val := strings.TrimSpace(parts[1])
+		segments := []PathSegment{}
+		for _, piece := range strings.Split(key, ".") {
+			if idx, err := strconv.Atoi(piece); err == nil {
+				segments = append(segments, PathSegment{Kind: "index", Index: idx})
+			} else {
+				segments = append(segments, PathSegment{Kind: "field", Key: piece})
+			}
+		}
+		if err := setPath(root, segments, parseLooseScalar(val)); err != nil {
+			return nil, err
+		}
+	}
+	return root, nil
+}
+
+func renderProperties(v *Value, joiner string, assignment string) string {
+	lines := []string{}
+	flattenValue("", v, joiner, func(path string, value *Value) {
+		sep := assignment
+		if assignment == "=" {
+			lines = append(lines, path+sep+stringifyScalar(value))
+		} else {
+			lines = append(lines, path+assignment+stringifyScalar(value))
+		}
+	})
+	if len(lines) == 0 {
+		return ""
+	}
+	return strings.Join(lines, "\n") + "\n"
+}
+
+func flattenValue(prefix string, v *Value, joiner string, emit func(path string, value *Value)) {
+	switch v.Kind {
+	case ObjectKind:
+		for _, pair := range v.Object.Pairs {
+			path := pair.Key
+			if prefix != "" {
+				path = prefix + joiner + path
+			}
+			flattenValue(path, pair.Value, joiner, emit)
+		}
+	case ArrayKind:
+		for i, item := range v.Array {
+			path := strconv.Itoa(i)
+			if prefix != "" {
+				path = prefix + joiner + path
+			}
+			flattenValue(path, item, joiner, emit)
+		}
+	default:
+		emit(prefix, v)
+	}
+}
+
+func parseINI(data string) (*Value, error) {
+	root := newObject()
+	current := root
+	for _, line := range strings.Split(data, "\n") {
+		line = strings.TrimSpace(line)
+		if line == "" || strings.HasPrefix(line, ";") || strings.HasPrefix(line, "#") {
+			continue
+		}
+		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
+			name := strings.TrimSpace(line[1 : len(line)-1])
+			section, ok := root.Get(name)
+			if !ok || section.Kind != ObjectKind {
+				section = ObjectValue(newObject())
+				root.Set(name, section)
+			}
+			current = section.Object
+			continue
+		}
+		parts := strings.SplitN(line, "=", 2)
+		if len(parts) != 2 {
+			continue
+		}
+		current.Set(strings.TrimSpace(parts[0]), parseLooseScalar(strings.TrimSpace(parts[1])))
+	}
+	return ObjectValue(root), nil
+}
+
+func renderINI(v *Value) string {
+	if v.Kind != ObjectKind {
+		return ""
+	}
+	var b strings.Builder
+	scalars := []Pair{}
+	sections := []Pair{}
+	for _, pair := range v.Object.Pairs {
+		if isScalar(pair.Value) {
+			scalars = append(scalars, pair)
+		} else if pair.Value.Kind == ObjectKind {
+			sections = append(sections, pair)
+		}
+	}
+	if len(scalars) > 0 {
+		width := 0
+		for _, pair := range scalars {
+			if len(pair.Key) > width {
+				width = len(pair.Key)
+			}
+		}
+		for _, pair := range scalars {
+			b.WriteString(pair.Key)
+			b.WriteString(strings.Repeat(" ", width-len(pair.Key)))
+			b.WriteString(" = ")
+			b.WriteString(stringifyScalar(pair.Value))
+			b.WriteString("\n")
+		}
+		if len(sections) > 0 {
+			b.WriteString("\n")
+		}
+	}
+	for i, section := range sections {
+		b.WriteString("[")
+		b.WriteString(section.Key)
+		b.WriteString("]\n")
+		for _, pair := range section.Value.Object.Pairs {
+			if isScalar(pair.Value) {
+				b.WriteString(pair.Key)
+				b.WriteString(" = ")
+				b.WriteString(stringifyScalar(pair.Value))
+				b.WriteString("\n")
+			}
+		}
+		if i < len(sections)-1 {
+			b.WriteString("\n")
+		}
+	}
+	return b.String()
+}
+
+func renderLua(v *Value) string {
+	var b strings.Builder
+	b.WriteString("return ")
+	writeLua(&b, v, 0)
+	b.WriteString(";\n")
+	return b.String()
+}
+
+func writeLua(b *strings.Builder, v *Value, level int) {
+	indent := strings.Repeat("\t", level)
+	switch v.Kind {
+	case NullKind:
+		b.WriteString("nil")
+	case BoolKind:
+		if v.Bool {
+			b.WriteString("true")
+		} else {
+			b.WriteString("false")
+		}
+	case NumberKind:
+		b.WriteString(v.Number)
+	case StringKind:
+		b.WriteString(strconv.Quote(v.String))
+	case ArrayKind:
+		b.WriteString("{\n")
+		for _, item := range v.Array {
+			b.WriteString(indent)
+			b.WriteString("\t")
+			writeLua(b, item, level+1)
+			b.WriteString(",\n")
+		}
+		b.WriteString(indent)
+		b.WriteString("}")
+	case ObjectKind:
+		b.WriteString("{\n")
+		for _, pair := range v.Object.Pairs {
+			b.WriteString(indent)
+			b.WriteString("\t[")
+			b.WriteString(strconv.Quote(pair.Key))
+			b.WriteString("] = ")
+			writeLua(b, pair.Value, level+1)
+			b.WriteString(";\n")
+		}
+		b.WriteString(indent)
+		b.WriteString("}")
+	}
+}
+
+func renderTOML(v *Value) string {
+	if v.Kind != ObjectKind {
+		return ""
+	}
+	var b strings.Builder
+	for _, pair := range v.Object.Pairs {
+		if isScalar(pair.Value) {
+			b.WriteString(pair.Key)
+			b.WriteString(" = ")
+			b.WriteString(renderTomlScalar(pair.Value))
+			b.WriteString("\n")
+		}
+	}
+	return b.String()
+}
+
+func renderHCL(v *Value) string {
+	return renderTOML(v)
+}
+
+func renderTomlScalar(v *Value) string {
+	switch v.Kind {
+	case StringKind:
+		return strconv.Quote(v.String)
+	default:
+		return stringifyScalar(v)
+	}
+}
