+	case "colors", "no-colors", "front-matter", "header-preprocess", "lua-globals", "lua-prefix", "lua-suffix", "lua-unquoted", "properties-array-brackets", "security-enable-system-operator", "split-exp", "split-exp-file", "string-interpolation", "tsv-auto-parse", "csv-auto-parse", "xml-attribute-prefix", "xml-content-name", "xml-directive-name", "xml-keep-namespace", "xml-proc-inst-prefix", "xml-raw-token", "xml-skip-directives", "xml-skip-proc-inst", "xml-strict-mode", "yaml-compact-seq-indent", "yaml-fix-merge-anchor-to-spec", "debug-node-info":
