+			return nil
+		case 'v':
+			opts.verbose = true
+		case 'I':
+			value, err := shortValue(rest, "I", args, i)
+			if err != nil {
+				return err
+			}
+			num, err := strconv.Atoi(value)
+			if err != nil {
+				return err
+			}
+			opts.indent = num
+			return nil
+		case 'p':
+			value, err := shortValue(rest, "p", args, i)
+			if err != nil {
+				return err
+			}
+			format, err := canonicalFormat(value)
+			if err != nil {
+				return err
+			}
+			opts.inputFormat = format
+			opts.inputFormatSet = true
+			return nil
+		case 'o':
+			value, err := shortValue(rest, "o", args, i)
+			if err != nil {
+				return err
+			}
