+	return nil
+}
+
+func shortValue(rest, name string, args []string, i *int) (string, error) {
+	if rest != "" {
+		return rest, nil
+	}
+	if *i+1 >= len(args) {
+		return "", fmt.Errorf("flag needs an argument: -%s", name)
