+	*i++
+	return args[*i], nil
+}
+
+func nextValue(name, value string, hasValue bool, args []string, i *int) (string, error) {
+	if hasValue {
+		return value, nil
+	}
+	if *i+1 >= len(args) {
+		return "", fmt.Errorf("flag needs an argument: --%s", name)
+	}
+	*i++
+	return args[*i], nil
+}
+
+func parseBoolFlag(value string, hasValue bool, fallback bool) bool {
+	if !hasValue {
+		return fallback
+	}
+	value = strings.TrimPrefix(value, "=")
+	if value == "false" {
+		return false
+	}
+	if value == "true" {
+		return true
+	}
+	return fallback
+}
+
